cypress_script:
describe('User Avatars Profile Links', () => {
  it('should reveal profile links on hover', () => {
    cy.visit('https://the-internet.herokuapp.com/hovers');
    cy.get('div#content .figure').first().trigger('mouseover');
    cy.contains('View profile').should('be.visible');
  });

  it('should not navigate when hovering without clicking', () => {
    cy.visit('https://the-internet.herokuapp.com/hovers');
    cy.get('div#content .figure').first().trigger('mouseover');
    cy.url().should('eq', 'https://the-internet.herokuapp.com/hovers');
    cy.contains('View profile').should('be.visible');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('User Avatars Profile Links', () => {
  test('should reveal profile links on hover', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/hovers');
    const avatar = page.locator('div#content .figure').first();
    await avatar.hover();
    await expect(page.locator('text=View profile')).toBeVisible();
  });

  test('should not navigate when hovering without clicking', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/hovers');
    const avatar = page.locator('div#content .figure').first();
    await avatar.hover();
    await expect(page).toHaveURL('https://the-internet.herokuapp.com/hovers');
    await expect(page.locator('text=View profile')).toBeVisible();
  });
});
